<script lang="ts">
 import original from '../data/atlas.json';import {get} from 'svelte/store';import {tick} from 'svelte';
 import {tr} from '../services/preferences';
 import {workspace,saveMethod,deleteMethod,saveScene,deleteScene,restoreScene,restoreMethod,legacyBackup} from '../services/workspace';
 import {loggedIn,signIn,signOut,changePassword} from '../services/local-account';
 import {download} from '../services/packages';
 import CaseStatusPanel from '../components/CaseStatusPanel.svelte';
 export let source:any,cases:any[],hidden:string[],imported:any[],section='';
 export let onremove:(c:any)=>Promise<void>,onrestore:(id:string)=>void,onupdate:(record:any,metadata:any)=>Promise<void>,onbackup:(value:any)=>Promise<void>,onadd:(id?:string)=>void;
 let authenticated=loggedIn(),user='',password='',message='',error=false,editing='',draft:any=null,search='',dataText='',refsText='',datasetsText='',crossText='',oldPassword='',nextPassword='',busy=false;
 $: scenes=source.stages.flatMap((st:any)=>st.scenes.map((s:any)=>({...s,stageId:st.id,stageName:st.name})));
 $: tab=['cases','methods','scenes','backup','account'].includes(section)?section:'overview';
 $: if(tab){editing='';draft=null;message=''}
 $: visibleCases=cases.filter(c=>!hidden.includes(c.id));
 const tabs=[['overview','概览'],['cases','案例管理'],['methods','技术管理'],['scenes','场景管理'],['backup','备份与迁移'],['account','账号设置']];
 const split=(text:string)=>text.split('\n').map(s=>s.trim()).filter(Boolean);
 function feedback(text:string,isError=false){message=text;error=isError}
 function login(event:SubmitEvent){event.preventDefault();try{signIn(user,password);password='';authenticated=true;feedback('登录成功')}catch(e){feedback(String((e as Error).message),true)}}
 async function edit(kind:string,id=''){
  editing=kind;message='';
  if(kind==='method')draft=id?{...source.methods[id],key:id}:{key:'',abbr:'',name:'',desc:'',signal:''};
  if(kind==='scene'){draft=id?structuredClone(scenes.find((s:any)=>s.id===id)):{id:'',name:'',stageId:source.stages[0].id,methods:[],diff:'中',intro:'',problem:'',point:'',diffWhy:'',data:[],refs:[],datasets:[],cross:[]};draft.diff=({'Low':'低','Medium':'中','High':'高'} as any)[draft.diff]||draft.diff;dataText=(draft.data||[]).map((r:any)=>Array.isArray(r)?r.join(' | '):r).join('\n');refsText=(draft.refs||[]).join('\n');datasetsText=(draft.datasets||[]).join('\n');crossText=(draft.cross||[]).join('\n')}
  if(kind==='case'){const c=cases.find(c=>c.id===id);draft={...c.manifest,methods:[...(c.manifest.methods||[])]}}
  if(id)draft.__existing=true;await tick();document.querySelector('.management-editor')?.scrollIntoView({block:'start'});document.querySelector<HTMLInputElement>('.management-editor input:not([readonly])')?.focus({preventScroll:true});
 }
 async function submit(event:SubmitEvent){event.preventDefault();busy=true;try{
  const {__existing,...value}=draft;
  if(editing==='method'){if(!__existing&&source.methods[value.key])throw Error('技术 ID 已存在');saveMethod(value)}
  else if(editing==='scene'){if(!__existing&&scenes.some((s:any)=>s.id===value.id))throw Error('场景 ID 已存在');saveScene({...value,data:split(dataText).map(row=>{const cells=row.split('|').map(v=>v.trim());return [cells[0]||'',cells[1]||'',cells[2]||'']}),refs:split(refsText),datasets:split(datasetsText),cross:split(crossText)},source)}
  else await onupdate(cases.find(c=>c.id===value.id),value);
  draft=null;editing='';feedback('已保存，站点立即生效')
 }catch(e){feedback((e as Error).message,true)}finally{busy=false}}
 function remove(kind:string,id:string){if(!confirm($tr('确认删除此项？')))return;try{if(kind==='method')deleteMethod(id,scenes,cases);else deleteScene(id,cases);feedback('已删除')}catch(e){feedback((e as Error).message,true)}}
 function reset(kind:string,id:string){try{if(kind==='method')restoreMethod(id);else restoreScene(id);feedback('已恢复内置内容')}catch(e){feedback((e as Error).message,true)}}
 function backup(){download('atlas-backup.json',JSON.stringify({format:'petroleum-atlas-backup',version:2,workspace:get(workspace),packages:imported,hidden},null,2))}
 async function restore(file:File|undefined){if(!file)return;busy=true;try{await onbackup(JSON.parse(await file.text()));feedback('备份恢复完成')}catch(e){feedback((e as Error).message,true)}finally{busy=false}}
 async function migrate(){busy=true;try{await onbackup(legacyBackup());feedback('同源旧版案例、技术、场景及隐藏名单已迁移，原数据保留')}catch(e){feedback((e as Error).message,true)}finally{busy=false}}
 function account(event:SubmitEvent){event.preventDefault();try{changePassword(oldPassword,nextPassword);oldPassword='';nextPassword='';feedback('密码已修改')}catch(e){feedback((e as Error).message,true)}}
</script>

<div class="page-head"><span class="eyebrow">LOCAL CONTENT WORKSPACE</span><h1>{$tr('本地内容管理')}</h1><p>{$tr('管理案例、技术类别和场景；所有更改保存在当前浏览器，可导出备份转移到其他电脑。')}</p></div>
{#if !authenticated}<form class="management-login paper" onsubmit={login}><h2>{$tr('管理员登录')}</h2><p>{$tr('首次使用账号 admin、密码 admin123；可在账号设置中修改密码。')}</p><label>{$tr('账号')}<input name="username" autocomplete="username" bind:value={user} required/></label><label>{$tr('密码')}<input name="password" type="password" autocomplete="current-password" bind:value={password} required/></label><button class="primary" type="submit">{$tr('登录')}</button><p>{$tr('此登录用于本机内容管理，不提供服务端身份认证。')}</p>{#if message}<p class:error role="status">{$tr(message)}</p>{/if}</form>
{:else}
<div class="management-toolbar"><nav aria-label={$tr('管理分区')}>{#each tabs as [id,label]}<a class:active={tab===id} href={'#/admin/'+(id==='overview'?'':id)}>{$tr(label)}</a>{/each}</nav><button onclick={()=>{signOut();authenticated=false;draft=null}}>{$tr('退出登录')}</button></div>
{#if message}<p class:error class="management-feedback" role="status">{$tr(message)}</p>{/if}
{#if tab==='overview'}<div class="workspace-counts"><div><strong>{cases.length}</strong><span>{$tr('案例')}</span></div><div><strong>{Object.keys(source.methods).length}</strong><span>{$tr('技术类别')}</span></div><div><strong>{scenes.length}</strong><span>{$tr('场景')}</span></div></div><div class="management-overview-actions"><a class="action-button secondary-button" href="#/matrix">{$tr('环节与方法矩阵')} ↗</a><a class="action-button secondary-button" href="#/admin/backup">{$tr('备份与迁移')} ↗</a><button class="primary" onclick={()=>onadd()}>{$tr('添加案例')} ＋</button></div><CaseStatusPanel cases={visibleCases} stages={source.stages} methods={source.methods} {onadd}/>
{:else if tab==='cases'}<h2>{$tr('案例管理')}</h2><p>{$tr('本地导入的案例可修改名称、所属场景、方法、版本与日期。内置案例保留源文件，可隐藏后单独恢复。')}</p><div class="management-list">{#each cases as c}<div class="management-row"><div><strong>{c.manifest.title}</strong><small>{c.id} · {c.manifest.version} · {c.manifest.updated} · {$tr(c.imported?'本地导入':hidden.includes(c.id)?'已隐藏':'内置案例')}</small></div><div class="row-actions">{#if c.imported}<button onclick={()=>edit('case',c.id)}>{$tr('编辑')}</button>{/if}{#if hidden.includes(c.id)}<button onclick={()=>onrestore(c.id)}>{$tr('恢复')}</button>{:else}<a class="action-button secondary-button" href={'#/scene/'+c.manifest.sceneId+'?case='+c.id}>{$tr('打开')}</a><button onclick={()=>onremove(c)}>{$tr(c.imported?'移除':'隐藏')}</button>{/if}</div></div>{/each}</div>
{:else if tab==='methods'}<div class="management-heading"><h2>{$tr('技术管理')}</h2><button class="primary" onclick={()=>edit('method')}>{$tr('新增技术类别')} ＋</button></div><div class="management-list">{#each Object.entries(source.methods) as [key,m]}<div class="management-row"><div><strong>{(m as any).abbr} · {(m as any).name}</strong><p>{(m as any).desc}</p><small>{key} · {scenes.filter((s:any)=>s.methods.includes(key)).length} {$tr('个场景')}</small></div><div class="row-actions"><button onclick={()=>edit('method',key)}>{$tr('编辑')}</button><button onclick={()=>remove('method',key)}>{$tr('删除')}</button>{#if $workspace.methods[key]&&!$workspace.methods[key].deleted&&Object.hasOwn(original.methods,key)}<button onclick={()=>reset('method',key)}>{$tr('撤销修改')}</button>{/if}</div></div>{/each}</div>{#each Object.entries($workspace.methods).filter(([,m])=>m.deleted) as [key]}<button onclick={()=>reset('method',key)}>{$tr('恢复')} {key}</button>{/each}
{:else if tab==='scenes'}<div class="management-heading"><h2>{$tr('场景管理')}</h2><button class="primary" onclick={()=>edit('scene')}>{$tr('新增场景')} ＋</button></div><input class="management-search" aria-label={$tr('搜索场景')} placeholder={$tr('搜索场景')} bind:value={search}/><div class="management-list">{#each scenes.filter((s:any)=>(s.id+s.name+s.stageName).toLowerCase().includes(search.toLowerCase())) as s}<div class="management-row"><div><strong>{s.name}</strong><small>{s.id} · {s.stageName} · {s.diff} · {s.methods.join(' / ')}</small></div><div class="row-actions"><a class="action-button secondary-button" href={'#/scene/'+s.id}>{$tr('打开')}</a><button onclick={()=>edit('scene',s.id)}>{$tr('编辑')}</button><button onclick={()=>remove('scene',s.id)}>{$tr('删除')}</button>{#if $workspace.scenes.upserts[s.id]&&original.stages.some(st=>st.scenes.some(row=>row.id===s.id))}<button onclick={()=>reset('scene',s.id)}>{$tr('撤销修改')}</button>{/if}</div></div>{/each}</div>{#if $workspace.scenes.deleted.length}<h3>{$tr('已删除场景')}</h3>{#each $workspace.scenes.deleted as id}<button onclick={()=>reset('scene',id)}>{$tr('恢复')} {id}</button>{/each}{/if}
{:else if tab==='backup'}<article class="paper"><h2>{$tr('备份与迁移')}</h2><p>{$tr('备份包含本地案例文件、技术和场景修改，以及隐藏名单。恢复前先校验全部记录；无效备份不会部分写入。')}</p><div class="management-overview-actions"><button class="primary" onclick={backup}>{$tr('导出完整备份')}</button><label class="file-label">{$tr('导入备份')}<input type="file" accept=".json" disabled={busy} onchange={e=>restore(e.currentTarget.files?.[0])}/></label><button disabled={busy} onclick={migrate}>{$tr('迁移同源旧版内容')}</button></div><p>{$tr('跨电脑或跨端口请使用备份文件；同源迁移读取原站 v1/v2 案例、技术和场景覆盖层。')}</p><a href="legacy/index.html#/admin" target="_blank" rel="noreferrer">{$tr('打开旧站完整内容管理')}</a></article>
{:else if tab==='account'}<form class="management-login paper" onsubmit={account}><h2>{$tr('修改密码')}</h2><label>{$tr('当前密码')}<input type="password" autocomplete="current-password" bind:value={oldPassword} required/></label><label>{$tr('新密码')}<input type="password" autocomplete="new-password" bind:value={nextPassword} minlength="6" required/></label><button class="primary" type="submit">{$tr('保存密码')}</button></form>{/if}
{#if draft}<section class="management-editor paper" aria-label={$tr('内容编辑器')}><div class="management-heading"><h2>{$tr(editing==='method'?'编辑技术':editing==='scene'?'编辑场景':'编辑案例')}</h2><button onclick={()=>{draft=null;editing=''}}>{$tr('取消')}</button></div><form onsubmit={submit}><div class="case-form">
{#if editing==='method'}<label>{$tr('技术 ID')}<input name="methodId" bind:value={draft.key} readonly={draft.__existing} required/></label><label>{$tr('缩写')}<input name="abbr" bind:value={draft.abbr} required/></label><label class="wide">{$tr('名称')}<input name="name" bind:value={draft.name} required/></label><label class="wide">{$tr('说明')}<textarea name="description" bind:value={draft.desc}></textarea></label><label class="wide">{$tr('适配任务')}<input name="signal" bind:value={draft.signal}/></label>
{:else}<label>{$tr(editing==='case'?'案例 ID':'场景 ID')}<input name="recordId" bind:value={draft.id} readonly={draft.__existing} required/></label><label>{$tr('名称')}{#if editing==='case'}<input name="name" bind:value={draft.title} required/>{:else}<input name="name" bind:value={draft.name} required/>{/if}</label>
{#if editing==='scene'}<label class="wide">{$tr('所属环节')}<select name="stageId" bind:value={draft.stageId}>{#each source.stages as st}<option value={st.id}>{st.name}</option>{/each}</select></label>{:else}<label class="wide">{$tr('所属场景')}<select name="sceneId" bind:value={draft.sceneId}>{#each source.stages as st}<optgroup label={st.name}>{#each st.scenes as s}<option value={s.id}>{s.id} · {s.name}</option>{/each}</optgroup>{/each}</select></label>{/if}
<fieldset class="wide"><legend>{$tr('涉及的 AI 技术')}</legend><div class="method-checks">{#each Object.entries(source.methods) as [id,m]}<label><input type="checkbox" value={id} bind:group={draft.methods}/>{(m as any).name}</label>{/each}</div></fieldset>
{#if editing==='case'}<label>{$tr('版本')}<input name="version" bind:value={draft.version}/></label><label>{$tr('更新日期')}<input name="updated" type="date" bind:value={draft.updated}/></label>
{:else}<label>{$tr('技术难度')}<select name="difficulty" bind:value={draft.diff}>{#each ['低','中','高'] as d}<option value={d}>{$tr(d)}</option>{/each}</select></label><label>{$tr('难度理由')}<textarea name="diffWhy" bind:value={draft.diffWhy}></textarea></label>{#each [['intro','专业场景介绍'],['problem','当前做法与问题'],['point','AI 介入点']] as [key,label]}<label class="wide">{$tr(label)}<textarea name={key} bind:value={draft[key]}></textarea></label>{/each}<label class="wide">{$tr('数据清单：每行 数据类型 | 规模规格 | 标注要求')}<textarea name="data" rows="4" bind:value={dataText}></textarea></label><label class="wide">{$tr('参考方向：每行一项')}<textarea name="refs" bind:value={refsText}></textarea></label><label>{$tr('公开数据集：每行一项')}<textarea name="datasets" bind:value={datasetsText}></textarea></label><label>{$tr('交叉环节：每行一个环节 ID')}<textarea name="cross" bind:value={crossText}></textarea></label>{/if}{/if}
</div><button class="primary" type="submit" disabled={busy}>{$tr('保存并应用')}</button></form></section>{/if}
{/if}
